package com.lims.service;

import com.lims.dao.ExportDAO;import com.lims.model.*;import java.util.*;

public class ExportService {
 private final ExportDAO dao=new ExportDAO();private final PurchasingService catalog=new PurchasingService();private final AuditLogService audit=new AuditLogService();
 public boolean sales(int id){return dao.hasRole(id,"Sales Staff");}public boolean warehouse(int id){return dao.hasRole(id,"Warehouse Staff");}
 public List<CustomerOption> customers(){return dao.customers();}public List<ProductOption> products(){return catalog.getProducts();}
 public List<ExportRequest> salesRequests(int user){return dao.salesRequests(user);}public List<ExportRequest> salesRequests(int user,String status,String search){return dao.salesRequests(user,status,search);}public List<ExportReceipt> receiptsBySalesStaff(int user){return dao.receiptsBySalesStaff(user);}public List<ExportRequest> managerRequests(String status){String s=status==null||status.isBlank()?"PENDING":status.toUpperCase();if(!Set.of("ALL","PENDING","APPROVED","REJECTED","COMPLETED").contains(s))throw new IllegalArgumentException("Bộ lọc trạng thái không hợp lệ.");return dao.managerRequests(s);}
 public List<ExportRequest> assignedRequests(int user){return dao.assignedRequests(user);}public ExportRequest request(int id){return dao.findRequest(id);}public List<InventoryOption> available(int id,int user){return dao.availableInventory(id,user);}public List<ExportReceipt> receipts(String s){String x=s==null||s.isBlank()?"PENDING_MANAGER":s.toUpperCase();if(!Set.of("ALL","PENDING_MANAGER","COMPLETED","REJECTED").contains(x))throw new IllegalArgumentException("Trạng thái phiếu xuất không hợp lệ.");return dao.receipts(x);}public List<ExportReceipt> receiptsByStaff(int id){return dao.receiptsByStaff(id);}
 public int createRequest(User actor,String customerValue,String[] products,String[] quantities,String ip,String agent){int customer;try{customer=Integer.parseInt(customerValue);}catch(Exception e){throw new IllegalArgumentException("Chọn khách hàng hợp lệ.");}if(dao.customers().stream().noneMatch(c->c.getCustomerId()==customer))throw new IllegalArgumentException("Khách hàng không tồn tại.");if(products==null||quantities==null||products.length==0||products.length!=quantities.length)throw new IllegalArgumentException("Thêm ít nhất một dòng sản phẩm.");Map<Integer,Integer> lines=new LinkedHashMap<>();Set<Integer> active=new HashSet<>();catalog.getProducts().forEach(p->active.add(p.getProductId()));for(int i=0;i<products.length;i++){try{int product=Integer.parseInt(products[i]),qty=Integer.parseInt(quantities[i]);if(!active.contains(product)||qty<1||qty>10000)throw new NumberFormatException();lines.merge(product,qty,Integer::sum);}catch(Exception e){throw new IllegalArgumentException("Model hoặc số lượng sản phẩm không hợp lệ.");}}List<ExportRequestItem> items=new ArrayList<>();lines.forEach((id,qty)->{ExportRequestItem x=new ExportRequestItem();x.setProductId(id);x.setQuantity(qty);items.add(x);});int id=dao.create(actor.getUserId(),customer,items,null);if(id<1)throw new IllegalStateException("Không tạo được yêu cầu xuất kho.");audit.logAction(actor.getUserId(),actor.getUsername(),"CREATE","EXPORT_REQUESTS",String.valueOf(id),null,Map.of("customerId",customer,"items",items),ip,agent);return id;}
 public void decideRequest(User manager,String idValue,String decision,String staffValue,String reason,String ip,String agent){int id,staff=0;try{id=Integer.parseInt(idValue);if("APPROVE".equalsIgnoreCase(decision))staff=Integer.parseInt(staffValue);}catch(Exception e){throw new IllegalArgumentException("Mã yêu cầu hoặc nhân viên kho không hợp lệ.");}boolean approve="APPROVE".equalsIgnoreCase(decision);if(!approve&&!("REJECT".equalsIgnoreCase(decision)))throw new IllegalArgumentException("Quyết định không hợp lệ.");if(approve&&!warehouse(staff))throw new IllegalArgumentException("Chọn nhân viên kho đang hoạt động.");String clean=reason==null?"":reason.trim();if(!approve&&(clean.isEmpty()||clean.length()>255))throw new IllegalArgumentException("Nhập lý do từ chối, tối đa 255 ký tự.");if(!dao.decideRequest(id,manager.getUserId(),staff,approve,approve?null:clean))throw new IllegalStateException("Không duyệt được yêu cầu; kiểm tra tồn khả dụng hoặc trạng thái yêu cầu.");audit.logAction(manager.getUserId(),manager.getUsername(),approve?"APPROVE":"REJECT","EXPORT_REQUESTS",String.valueOf(id),Map.of("status","PENDING"),Map.of("status",approve?"APPROVED":"REJECTED","assignedTo",staff,"reason",clean),ip,agent);}
 public int createReceipt(User actor,String idValue,String[] serials,String note,String ip,String agent){int id;try{id=Integer.parseInt(idValue);}catch(Exception e){throw new IllegalArgumentException("Mã yêu cầu xuất không hợp lệ.");}if(note!=null&&note.trim().length()>255)throw new IllegalArgumentException("Ghi chú tối đa 255 ký tự.");int receipt=dao.createReceipt(id,actor.getUserId(),serials,note==null?null:note.trim());if(receipt<1)throw new IllegalStateException("Không tạo được phiếu xuất. Kiểm tra đúng nhân viên, số lượng theo model, serial còn trong kho và không có phiếu chờ duyệt.");audit.logAction(actor.getUserId(),actor.getUsername(),"SUBMIT","EXPORT_RECEIPTS",String.valueOf(receipt),null,Map.of("requestId",id,"serials",serials.length,"status","PENDING_MANAGER"),ip,agent);return receipt;}
 public void decideReceipt(User manager,String receiptValue,String decision,String reason,String ip,String agent){int id;try{id=Integer.parseInt(receiptValue);}catch(Exception e){throw new IllegalArgumentException("Mã phiếu xuất không hợp lệ.");}boolean approve="APPROVE".equalsIgnoreCase(decision);if(!approve&&!("REJECT".equalsIgnoreCase(decision)))throw new IllegalArgumentException("Quyết định không hợp lệ.");String clean=reason==null?"":reason.trim();if(!approve&&(clean.isEmpty()||clean.length()>255))throw new IllegalArgumentException("Nhập lý do từ chối, tối đa 255 ký tự.");if(!dao.decideReceipt(id,manager.getUserId(),approve,approve?null:clean))throw new IllegalStateException("Không xử lý được phiếu xuất; serial có thể đã thay đổi trạng thái.");audit.logAction(manager.getUserId(),manager.getUsername(),approve?"APPROVE":"REJECT","EXPORT_RECEIPTS",String.valueOf(id),Map.of("status","PENDING_MANAGER"),Map.of("status",approve?"COMPLETED":"REJECTED","reason",clean),ip,agent);}

 public ExportReceipt getReceiptDetail(int receiptId){return dao.findReceiptById(receiptId);}

}
